(2, 'Neva Loy', 'loy.neva51@gmail.com', 'Unlock E-Commerce Potential with our E-Commerce Mastery E-Book ������', '079 8218 9834', 'Great news for e-commerce owners and managers!\r\n\r\nOur latest e-book, \"E-Commerce Mastery: Proven Strategies for Your Online Store,\" is now available, packed with valuable insights to elevate your online business.\r\n\r\nDownload Your Copy Now: https://ecomgrowthguide.com/\r\n\r\nDon\'t miss out on this opportunity to transform your online store. Here\'s to your continued success in the world of e-commerce!', NULL, NULL, '2024-01-19 19:09:58', '2024-01-19 19:09:58'),
(3, 'Natasha Janpe', 'natasha@refsmedia.com', 'Important', '2164287311', 'We’ve developed a strategy focused on the Ecom stores only, where you can maximize sales with FREE traffic. Check this YouTube video we’ve recorded: https://www.youtube.com/watch?v=ryzlMw3isQo\r\n\r\nYour store has the potential, and we want to take this responsibility. Let’s arrange a live strategy session to discuss how we can achieve the same for your store. \r\n\r\nTell me when you’re available?', NULL, NULL, '2024-04-15 00:01:30', '2024-04-15 00:01:30'),
(4, 'Nicholas K', 'pat@aneesho.com', 'Design Work', '8102440753', 'Do you need help with graphic design - brochures, banners, flyers, advertisements, social media posts, logos etc? \r\n\r\nWe charge a low fixed monthly fee. Let me know if you\'re interested and would like to see our portfolio.', NULL, NULL, '2024-04-26 04:50:08', '2024-04-26 04:50:08'),
(5, 'Nicholas K', 'pat@aneesho.com', 'Design Work', '8102440753', 'Do you need help with graphic design - brochures, banners, flyers, advertisements, social media posts, logos etc? \r\n\r\nWe charge a low fixed monthly fee. Let me know if you\'re interested and would like to see our portfolio.', NULL, NULL, '2024-04-26 05:02:59', '2024-04-26 05:02:59'),
(6, 'Ndegwa Maina', 'info@aaes.co.ke', 'MATSON COOKER RFQ', '0716694977', 'Please quote for a Mattson cooker with its accessories', NULL, NULL, '2025-02-17 12:33:24', '2025-02-17 12:33:24'),
(7, 'Steve Cullen', 'steve@consumerprodemail.com', 'Expanding Distribution', '1575275765', 'Hello, I\'m Steve Cullen with Consumer Products International ( https://www.consumerproductsintl.com ).\r\n\r\nAt CPI, we specialize in helping domestic and international consumer brands expand their reach in the US market. With decades of experience and billions in generated revenue, we offer a comprehensive solution for manufacturers looking to enter or grow in America\'s consumer market.\r\n\r\nOur services include:\r\n* Distribution to major retailers (C-Stores, Food/Drug/Mass, Home Centers, Online)\r\n* FDA/Regulatory guidance\r\n* Sales and marketing support (TV, Public Relations Campaigns)\r\n* Warehousing and logistics\r\n\r\nWe pride ourselves on our turnkey approach and ability to quickly bring products to market. Our team\'s expertise and established relationships with national and regional retail chains give your brand a competitive edge.\r\n\r\nTo discuss how we can help your brand succeed in the US market, please contact us or schedule a call at https://calendly.com/stevecullen-nutricompanyinc/15-minute-call-cpi \r\n\r\nBest regards,\r\nSteve Cullen\r\nConsumer Products International', NULL, NULL, '2025-03-18 06:56:55', '2025-03-18 06:56:55');

